"Мантія очей":"Robe of eyes",
"Бачиш на всі боки, темний зір, бачиш невидимих і на Ефірний план.":"You see in all directions, have darkvision and see invisible things and into the Ethereal Plane.",
"Мотузка сплутування":"Rope of entanglement",
"Обплутує ціль у межах 20 фт (рятівний Спритності СК 15).":"Entangles a target within 20 ft (Dexterity save DC 15).",
"Килим-літак":"Carpet of flying",
"Літає за командою, швидкість і вантаж залежать від розміру.":"Flies on command; speed and load depend on its size.",
"Кришталева куля":"Crystal ball",
"Твориш «Підглядання» (СК 17).":"You can cast “Scrying” (DC 17).",
