"Персонаж, який уже в іншій події, перейде в цю.":"A character already in another event will move to this one.",
"{0} — хто бере участь у події":"{0} — who takes part in the event",
"Персонаж з іншої події перейде в цю. Якщо інша подія залишиться без учасників — вона перетече в цю, звіт буде спільний. Прибереш усіх — подія завершиться, а звіт прийде в чат.":"A character from another event will move to this one. If the other event is left with no participants, it flows into this one and the report is shared. Remove everyone and the event ends, with the report sent to the chat.",
