"Завершити сесію {0}? Активні події завершаться. Усе стиснеться до підсумку (рівень, досвід, гроші, предмети, ХП, натхнення, події) — він прийде тобі файлом у чат із ботом, гравці отримають сповіщення. Детальний журнал і кидки сесії буде видалено: якщо він потрібен, спершу надішли його з «📜 Журнал».":"End session {0}? Active events will end. Everything is condensed into a summary (level, XP, money, items, HP, inspiration, events) — it arrives as a file in the bot chat, and players get a notification. The session’s detailed log and rolls will be deleted: if you need the log, send it first from “📜 Log”.",
