"Попадання":"Hit",
"Кидки гравців цієї сесії. Познач ✓ / ✗ — гравець побачить позначку, вона потрапить і у звіт події. 🗑 — видалити кидок звідусіль.":"Players’ rolls this session. Mark ✓ / ✗ — the player will see the mark, and it goes into the event report too. 🗑 — delete the roll everywhere.",
